		validator.validate( command );

            entity.setInspectionCharacteristicId( command.getInspectionCharacteristicId() );
            entity.setCharacteristicCode( command.getCharacteristicCode() );
            entity.setName( command.getName() );
            entity.setLowerSpecLimit( command.getLowerSpecLimit() );
            entity.setUpperSpecLimit( command.getUpperSpecLimit() );
            entity.setTarget( command.getTarget() );
            entity.setInspectionPlan( command.getInspectionPlan() );
            entity.setMeasurementType( command.getMeasurementType() );

		// ------------------------------------------
		// persist an existing one
